/* ---------- Thread panel ---------- */
.thp{display:flex;flex-direction:column;height:360px;overflow:hidden}
.thp-tabs{display:flex;gap:var(--s-1);padding:var(--s-2) var(--s-2) 0;border-bottom:1px solid color-mix(in srgb,var(--line) 50%,transparent);position:relative;overflow-x:auto;scrollbar-width:none}
.thp-tab{display:flex;align-items:center;gap:7px;white-space:nowrap;flex:none;padding:7px 10px 10px;font-size:13px;color:var(--muted);position:relative;transition:color .25s}
@media (hover:hover) and (pointer:fine){.thp-tab:hover{color:var(--fg2)}}
/* the tabs scroll sideways, which would cut an outside ring: theirs is drawn inside */
.thp-tab:focus-visible{outline-offset:-2px}
.thp-tab[aria-selected="true"]{color:var(--fg)}
.thp-tab .dot{width:6px;height:6px}
.thp-ink{position:absolute;bottom:-1px;height:2px;border-radius:2px;background:var(--fg);transition:left .5s var(--ease),width .5s var(--ease)}
.thp-body{flex:1;overflow-y:auto;padding:14px;display:flex;flex-direction:column;gap:var(--s-3);scrollbar-width:thin}
.thp-body .bub{font-size:13.5px}
.thp-ag{font-size:13.5px;line-height:1.6;color:var(--fg)}
.thp-ag .src{display:flex;gap:6px;margin-bottom:6px;flex-wrap:wrap}
.thp-in{display:flex;align-items:center;gap:var(--s-2);margin:0 10px 10px;padding:var(--s-1) var(--s-1) var(--s-1) var(--s-3);border-radius:var(--r-field);background:var(--surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--field-line) 50%,transparent);transition:box-shadow var(--t-fast)}
@supports (corner-shape:squircle){.thp-in{corner-shape:squircle;border-radius:var(--r-field-sq)}}
.thp-in:has(.thp-field:focus){box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--field-line-strong) 50%,transparent)}
.thp-field{flex:1;min-width:0;border:0;outline:0;background:none;font-size:13.5px;height:32px}
.thp-field::placeholder{color:var(--muted)}
.thp-send{width:28px;height:28px;border-radius:50%;display:grid;place-items:center;background:var(--accent);color:var(--on-accent);transition:opacity .25s,transform .15s}
.thp-send[disabled]{opacity:1;cursor:not-allowed;background:var(--dis-hatch),var(--dis-fill);color:var(--dis);box-shadow:var(--soft-ring)}
.thp-send:active{transform:scale(.92)}

DM.def('thread-panel', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{up}', I('up'));
  const T = [
    { t:'Onboarding', col:'var(--ok)', msgs:[['u','Why is the workspace step losing people?'],['a','It asks for a team name before anyone has made anything. Moving it after the first project, with the name filled from the email domain, should help.', ['Funnel data','Session notes']]] },
    { t:'Tokens', col:'var(--warn)', msgs:[['u','Which colours are still hard-coded?'],['a','Eleven, mostly greys in Button and Card. I can swap them for tokens in one pass.', ['tokens.ts']]] },
    { t:'Launch email', col:'var(--faint)', msgs:[['u','Draft the launch email for Friday.'],['a','Two subject lines are ready. The shorter one tested better with the team.', []]] }
  ];
  let cur = 0;
  const tabs = $('.thp-tabs', r), body = $('.thp-body', r), field = $('.thp-field', r), send = $('.thp-send', r);
  tabs.innerHTML = T.map((t, i) => `<button class="thp-tab" role="tab" aria-selected="${i === 0}"><span class="dot" style="color:${t.col}"></span>${t.t}</button>`).join('') + '<span class="thp-ink"></span>';
  const ink = $('.thp-ink', r), tbs = $$('.thp-tab', r);
  const place = () => { const b = tbs[cur]; ink.style.left = b.offsetLeft + 10 + 'px'; ink.style.width = b.offsetWidth - 20 + 'px'; };
  const msg = (m, anim) => { const el = m[0] === 'u' ? html(`<div class="bub">${m[1]}</div>`) : html(`<div class="thp-ag">${m[2] && m[2].length ? `<div class="src">${m[2].map(s => `<button class="fchip lnk" data-tip="${({ 'Funnel data':'Amplitude, last 30 days', 'Session notes':'Notion, 8 interviews', 'tokens.ts':'src/styles/tokens.ts' })[s] || s}">${I('file-text','xs')}${s}</button>`).join('')}</div>` : ''}${m[1]}</div>`); body.appendChild(el); if (anim){ enter(el); body.scrollTo({ top:body.scrollHeight, behavior:REDUCE ? 'auto' : 'smooth' }); } else body.scrollTop = body.scrollHeight; return el; };
  function show(i){ cur = i; tbs.forEach((b, k) => b.setAttribute('aria-selected', k === i)); place(); body.innerHTML = ''; T[i].msgs.forEach((m, k) => { const el = msg(m); enter(el, k * 70); }); }
  tbs.forEach((b, i) => b.onclick = () => show(i));
  field.oninput = () => { send.disabled = !field.value.trim(); };
  $('.thp-in', r).onsubmit = e => { e.preventDefault(); const v = field.value.trim(); if (!v) return; field.value = ''; send.disabled = true;
    const m = ['u', v]; T[cur].msgs.push(m); msg(m, true);
    const th = html('<div class="thp-ag"><span class="shim">Thinking</span></div>'); body.appendChild(th); enter(th);
    const k = cur; c.later(1400, () => { th.remove(); const a = ['a', 'On it. I\'ll update this thread when it\'s done.', []]; T[k].msgs.push(a); if (cur === k) msg(a, true); });
  };
  requestAnimationFrame(() => show(0)); new ResizeObserver(place).observe(tabs);
  // once the card has settled, a reply is typed and sent in place, unless someone has started using it
  // the preview asks a follow-up by itself; clicking, focusing or typing in it takes over, and what it had typed goes
  c.run(async () => {
    await c.step(1800);
    await c.type(field, 'Can you make that change now?', { ms:() => 32 + Math.random() * 40, each:() => { send.disabled = !field.value.trim(); }, keep:true });
    await c.step(380); $('.thp-in', r).requestSubmit();
  });
});
